-- Guard: all three rows must exist and must carry no promise phrase.
DO $guard$
DECLARE
  v_missing text;
  v_dirty   text;
BEGIN
  SELECT string_agg(s, ', ') INTO v_missing
  FROM unnest(ARRAY['designer-invite', 'milestone-first-payment', 'onboarding-aesthete']) AS s
  WHERE NOT EXISTS (SELECT 1 FROM public.email_templates t WHERE t.slug = s);

  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION '00655: email_templates row(s) missing, nothing was updated for: %', v_missing;
  END IF;

  SELECT string_agg(t.slug, ', ') INTO v_dirty
  FROM public.email_templates t
  WHERE t.slug IN ('designer-invite', 'milestone-first-payment', 'onboarding-aesthete')
    AND (t.html_content ILIKE '%pledge%'
      OR t.html_content ILIKE '%quarter of our commission%'
      OR t.html_content ILIKE '%share in what it earns%');

  IF v_dirty IS NOT NULL THEN
    RAISE EXCEPTION '00655: promise copy still present after update in: %', v_dirty;
  END IF;

  RAISE NOTICE '00655: three templates carry no Pledge/commission-share copy.';
END
$guard$;
